SELECT
	LOG_ID, EVENT_TYPE, USER_ID, USER_NM, MENU_ID, TARGET_TYPE, TARGET_ID,
	REQUEST_URI, HTTP_METHOD, CLIENT_IP, RESULT, DETAIL, REGIST_DT
FROM AUDIT_LOG
WHERE 1 = 1

	AND EVENT_TYPE = #{eventType}


	AND (USER_ID LIKE '%' || #{searchKeyword} || '%'
		OR TARGET_ID LIKE '%' || #{searchKeyword} || '%'
		OR REQUEST_URI LIKE '%' || #{searchKeyword} || '%')


	AND REGIST_DT >= #{startDate}


	AND REGIST_DT < #{endDate}

ORDER BY REGIST_DT DESC
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM AUDIT_LOG
WHERE 1 = 1

	AND EVENT_TYPE = #{eventType}


	AND (USER_ID LIKE '%' || #{searchKeyword} || '%'
		OR TARGET_ID LIKE '%' || #{searchKeyword} || '%'
		OR REQUEST_URI LIKE '%' || #{searchKeyword} || '%')


	AND REGIST_DT >= #{startDate}


	AND REGIST_DT < #{endDate}
